// Support contact number is set directly in the footer's Call/WhatsApp links below

/* Storage abstraction: uses Claude's built-in artifact storage when this
   runs inside a Claude preview, and falls back to the browser's localStorage
   when deployed on a real host (e.g. Vercel/Netlify) where window.storage
   does not exist. The localStorage fallback is per-device only — see the
   deployment notes for wiring up a real shared backend. */
const hasClaudeStorage = typeof window !== "undefined" && typeof window.storage !== "undefined";

async function storageSet(key, value) {
  if (hasClaudeStorage) return window.storage.set(key, value, true);
  try {
    localStorage.setItem(key, value);
    return { key, value, shared: true };
  } catch (e) {
    return null;
  }
}

async function storageGet(key) {
  if (hasClaudeStorage) return window.storage.get(key, true);
  const value = localStorage.getItem(key);
  if (value === null) throw new Error("Key not found");
  return { key, value, shared: true };
}

async function storageList(prefix) {
  if (hasClaudeStorage) return window.storage.list(prefix, true);
  const keys = Object.keys(localStorage).filter((k) => k.startsWith(prefix));
  return { keys, prefix, shared: true };
}

/* IMPORTANT — read before deploying outside Claude:
   Once this site is hosted on a real domain, window.storage no longer
   exists, so the fallback above uses localStorage — which is PER DEVICE.
   That means the "Store Owner" panel would only see orders placed from
   that exact same browser, not real customer orders from their phones.

   To receive real orders after deployment, sign up for a free form
   backend (e.g. https://formspree.io — 2 minute signup, no code) and
   paste your endpoint URL below. Every order will then also be emailed
   to you automatically, regardless of device. Leave it blank to skip. */
const ORDER_NOTIFY_ENDPOINT = ""; // e.g. "https://formspree.io/f/xxxxxxx"

async function notifyOrder(order) {
  if (!ORDER_NOTIFY_ENDPOINT) return;
  try {
    await fetch(ORDER_NOTIFY_ENDPOINT, {
      method: "POST",
      headers: { "Content-Type": "application/json", Accept: "application/json" },
      body: JSON.stringify(order),
    });
  } catch (e) {
    /* best effort — order is already saved locally either way */
  }
}

const CATEGORIES = ["All", "Horse Editions", "Heritage Patterns", "Art & Calligraphy"];
const SIZES = [
  { id: "S", label: "Small · 40×50cm", price: 1000 },
  { id: "M", label: "Medium · 60×80cm", price: 1800 },
  { id: "L", label: "Large · 80×110cm", price: 3300 },
];
const FRAMES = ["Natural Oak", "Walnut", "Matte Black"];

function egp(n) {
  return `${n.toLocaleString()} EGP`;
}

/* ---- Signature element: procedural corner ornament, echoing the
   carpet corner-medallions seen throughout the source gallery ---- */
function CornerOrnament({ color = COLORS.gold, size = 64, className = "" }) {
  return (
    <svg width={size} height={size} viewBox="0 0 64 64" className={className} fill="none">
      <path d="M2 2 H20 M2 2 V20" stroke={color} strokeWidth="1.5" />
      <path d="M2 30 Q2 2 30 2" stroke={color} strokeWidth="1" opacity="0.6" />
      <circle cx="14" cy="14" r="3" stroke={color} strokeWidth="1" />
      <circle cx="2" cy="2" r="2" fill={color} />
      <path d="M8 26 Q26 26 26 8" stroke={color} strokeWidth="0.75" opacity="0.4" />
    </svg>
  );
}

/* ---- Framed photo tile used on every product card and in the modal ---- */
function FramedPhoto({ src, alt }) {
  return (
    <div className="relative w-full aspect-[4/5] overflow-hidden" style={{ background: COLORS.ink }}>
      <img src={src} alt={alt} className="w-full h-full object-cover" />
      <div className="absolute inset-0 pointer-events-none" style={{ boxShadow: `inset 0 0 0 1px ${COLORS.gold}55` }} />
    </div>
  );
}

